const input=$json.body??$json;
const status=String(input.status??input.transaction_status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const sellerId=input.seller_id??input.seller_contact_id;
const buyerId=input.buyer_id??input.assignee_id;
const closingDate=String(input.closing_date??'').trim();
const roles=input.coordination_roles??{};
const titleReady=Boolean(input.title_company??input.title_ready??roles.title);
const attorneyReady=Boolean(input.attorney??input.attorney_ready??roles.attorney);
const fundingReady=Boolean(input.funding_source??input.funding_ready??roles.funding);
const brokerReady=Boolean(input.broker??input.broker_ready??roles.broker);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dnc=input.dnc===true;
const identityReady=Boolean(dealId&&leadId&&propertyId&&sellerId&&buyerId);
let coordination_status='needs_review',next='WF-126',reason='closing coordination requires review';
if(dnc){coordination_status='blocked_dnc';next='WF-126';reason='DNC/contact restriction';}
else if(blockers.length){coordination_status='blocked';next='WF-126';reason='active closing blockers';}
else if(status!=='transaction_ready'){coordination_status='transaction_not_ready';next='WF-323';reason='transaction readiness not confirmed';}
else if(!identityReady){coordination_status='incomplete_parties';next='WF-126';reason='seller/buyer/deal/property identity incomplete';}
else if(!closingDate){coordination_status='closing_date_required';next='WF-126';reason='closing date missing';}
else if(!titleReady||!attorneyReady||!fundingReady||!brokerReady){coordination_status='coordination_incomplete';next='WF-325';reason='one or more closing coordination roles are not ready';}
else{coordination_status='coordination_ready';next='WF-325';reason='title, attorney, funding, broker and parties validated for closing coordination';}
return [{json:{...input,workflow_id:'WF-324',workflow_name:'Transaction Readiness → Title / Attorney / Funding / Broker Closing Coordination Controller',coordination_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,seller_id:sellerId||null,buyer_id:buyerId||null,closing_date:closingDate||null,coordination_roles:{title:titleReady,attorney:attorneyReady,funding:fundingReady,broker:brokerReady},next_workflow:next,human_review_required:coordination_status!=='coordination_ready',crm_activity:{activity_type:'closing_coordination',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:coordination_status,closing_date:closingDate||null,reason}}}];
